package com.company.generated.units.u5ce9c9ef500c;

import java.math.BigDecimal;

public class TransferFundsRQUnformatMapper {

    public TransferFundsRQBusinessInput toBusinessInput(TransferFundsRQWireModel wire) {
        if (wire == null) {
            return null;
        }

        TransferFundsRQBusinessInput input = new TransferFundsRQBusinessInput();

        // SourceAccount: CCPadding padChar=0, length=10 (padLeft=true by default)
        // Unformat strips padding
        String srcAcc = wire.sourceAccount;
        if (srcAcc != null) {
            srcAcc = srcAcc.replaceFirst("^0+", "");
            if (srcAcc.isEmpty()) {
                srcAcc = "0";
            }
        }
        input.setSourceAccount(srcAcc);

        // TargetAccount: CCPadding padChar=0, length=10
        String tgtAcc = wire.targetAccount;
        if (tgtAcc != null) {
            tgtAcc = tgtAcc.replaceFirst("^0+", "");
            if (tgtAcc.isEmpty()) {
                tgtAcc = "0";
            }
        }
        input.setTargetAccount(tgtAcc);

        // Amount: NumberFormat showThousandsSep=no, showDecimalsSep=yes
        String amtStr = wire.amount;
        if (amtStr != null && !amtStr.isBlank()) {
            amtStr = amtStr.replace(",", "").trim();
            input.setAmount(new BigDecimal(amtStr));
        } else {
            input.setAmount(null);
        }

        // Currency: CCPadding padChar=' ', length=3
        String curr = wire.currency;
        if (curr != null) {
            curr = curr.replaceFirst("\\s+$", "");
        }
        input.setCurrency(curr);

        // SessionToken: MaskLogDecorator (no-op on unformat)
        input.setSessionToken(wire.sessionToken);

        // TransferReference: nilDecorator
        String tRef = wire.transferReference;
        if (tRef == null || tRef.isEmpty()) {
            input.setTransferReference(null);
        } else {
            input.setTransferReference(tRef);
        }

        // ScheduledDate: nilDecorator
        String sDate = wire.scheduledDate;
        if (sDate == null || sDate.isEmpty()) {
            input.setScheduledDate(null);
        } else {
            input.setScheduledDate(sDate);
        }

        return input;
    }
}

package com.company.generated.units.u5ce9c9ef500c;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

public class TransferFundsRQUnformatMapperTest {

    @Test
    public void testUnformatTransferFundsRequest() {
        TransferFundsRQWireModel wire = new TransferFundsRQWireModel();
        wire.sourceAccount = "0000123456";
        wire.targetAccount = "0000654321";
        wire.amount = "1500.50";
        wire.currency = "USD";
        wire.sessionToken = "token-abc-123";
        wire.transferReference = "REF-999";
        wire.scheduledDate = "2023-12-31";

        TransferFundsRQUnformatMapper mapper = new TransferFundsRQUnformatMapper();
        TransferFundsRQBusinessInput input = mapper.toBusinessInput(wire);

        assertNotNull(input);
        assertEquals("123456", input.getSourceAccount());
        assertEquals("654321", input.getTargetAccount());
        assertEquals(new BigDecimal("1500.50"), input.getAmount());
        assertEquals("USD", input.getCurrency());
        assertEquals("token-abc-123", input.getSessionToken());
        assertEquals("REF-999", input.getTransferReference());
        assertEquals("2023-12-31", input.getScheduledDate());
    }

    @Test
    public void testNilAndOptionalDecorators() {
        TransferFundsRQWireModel wire = new TransferFundsRQWireModel();
        wire.sourceAccount = "0000000001";
        wire.targetAccount = "0000000002";
        wire.amount = "100.00";
        wire.currency = "EUR";
        wire.sessionToken = "tok";
        wire.transferReference = null;
        wire.scheduledDate = "";

        TransferFundsRQUnformatMapper mapper = new TransferFundsRQUnformatMapper();
        TransferFundsRQBusinessInput input = mapper.toBusinessInput(wire);

        assertNotNull(input);
        assertNull(input.getTransferReference());
        assertNull(input.getScheduledDate());
    }
}

